sealed class FfiPaymentMethod {
    
    data class Onchain(
        val `method`: FfiOnchainMethod) : FfiPaymentMethod() {
        companion object
    }
    
    data class Lightning(
        val `method`: FfiLightningMethod) : FfiPaymentMethod() {
        companion object
    }
    
    data class Ark(
        val `method`: FfiArkMethod) : FfiPaymentMethod() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiPaymentMethod : FfiConverterRustBuffer<FfiPaymentMethod>{
    override fun read(buf: ByteBuffer): FfiPaymentMethod {
        return when(buf.getInt()) {
            1 -> FfiPaymentMethod.Onchain(
                FfiConverterTypeFfiOnchainMethod.read(buf),
                )
            2 -> FfiPaymentMethod.Lightning(
                FfiConverterTypeFfiLightningMethod.read(buf),
                )
            3 -> FfiPaymentMethod.Ark(
                FfiConverterTypeFfiArkMethod.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiPaymentMethod) = when(value) {
        is FfiPaymentMethod.Onchain -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiOnchainMethod.allocationSize(value.`method`)
            )
        }
        is FfiPaymentMethod.Lightning -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiLightningMethod.allocationSize(value.`method`)
            )
        }
        is FfiPaymentMethod.Ark -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiArkMethod.allocationSize(value.`method`)
            )
        }
    }

    override fun write(value: FfiPaymentMethod, buf: ByteBuffer) {
        when(value) {
            is FfiPaymentMethod.Onchain -> {
                buf.putInt(1)
                FfiConverterTypeFfiOnchainMethod.write(value.`method`, buf)
                Unit
            }
            is FfiPaymentMethod.Lightning -> {
                buf.putInt(2)
                FfiConverterTypeFfiLightningMethod.write(value.`method`, buf)
                Unit
            }
            is FfiPaymentMethod.Ark -> {
                buf.putInt(3)
                FfiConverterTypeFfiArkMethod.write(value.`method`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





sealed class FfiQuoteResponse {
    
    data class Ok(
        val `recipient`: FfiQuoteRecipient, 
        val `selectedMethod`: FfiPaymentMethod, 
        val `feeSats`: kotlin.ULong, 
        val `eta`: kotlin.String, 
        val `reason`: kotlin.String, 
        val `qr`: kotlin.String, 
        val `execution`: FfiExecutionMode, 
        val `walletHint`: kotlin.String) : FfiQuoteResponse() {
        companion object
    }
    
    data class NotRegistered(
        val `invite`: FfiInvite) : FfiQuoteResponse() {
        companion object
    }
    
    data class NoRoute(
        val `reason`: kotlin.String) : FfiQuoteResponse() {
        companion object
    }
    
    data class InvalidSignature(
        val `recipient`: FfiQuoteRecipient) : FfiQuoteResponse() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiQuoteResponse : FfiConverterRustBuffer<FfiQuoteResponse>{
    override fun read(buf: ByteBuffer): FfiQuoteResponse {
        return when(buf.getInt()) {
            1 -> FfiQuoteResponse.Ok(
                FfiConverterTypeFfiQuoteRecipient.read(buf),
                FfiConverterTypeFfiPaymentMethod.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterTypeFfiExecutionMode.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> FfiQuoteResponse.NotRegistered(
                FfiConverterTypeFfiInvite.read(buf),
                )
            3 -> FfiQuoteResponse.NoRoute(
                FfiConverterString.read(buf),
                )
            4 -> FfiQuoteResponse.InvalidSignature(
                FfiConverterTypeFfiQuoteRecipient.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiQuoteResponse) = when(value) {
        is FfiQuoteResponse.Ok -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiQuoteRecipient.allocationSize(value.`recipient`)
                + FfiConverterTypeFfiPaymentMethod.allocationSize(value.`selectedMethod`)
                + FfiConverterULong.allocationSize(value.`feeSats`)
                + FfiConverterString.allocationSize(value.`eta`)
                + FfiConverterString.allocationSize(value.`reason`)
                + FfiConverterString.allocationSize(value.`qr`)
                + FfiConverterTypeFfiExecutionMode.allocationSize(value.`execution`)
                + FfiConverterString.allocationSize(value.`walletHint`)
            )
        }
        is FfiQuoteResponse.NotRegistered -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiInvite.allocationSize(value.`invite`)
            )
        }
        is FfiQuoteResponse.NoRoute -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is FfiQuoteResponse.InvalidSignature -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiQuoteRecipient.allocationSize(value.`recipient`)
            )
        }
    }

    override fun write(value: FfiQuoteResponse, buf: ByteBuffer) {
        when(value) {
            is FfiQuoteResponse.Ok -> {
                buf.putInt(1)
                FfiConverterTypeFfiQuoteRecipient.write(value.`recipient`, buf)
                FfiConverterTypeFfiPaymentMethod.write(value.`selectedMethod`, buf)
                FfiConverterULong.write(value.`feeSats`, buf)
                FfiConverterString.write(value.`eta`, buf)
                FfiConverterString.write(value.`reason`, buf)
                FfiConverterString.write(value.`qr`, buf)
                FfiConverterTypeFfiExecutionMode.write(value.`execution`, buf)
                FfiConverterString.write(value.`walletHint`, buf)
                Unit
            }
            is FfiQuoteResponse.NotRegistered -> {
                buf.putInt(2)
                FfiConverterTypeFfiInvite.write(value.`invite`, buf)
                Unit
            }
            is FfiQuoteResponse.NoRoute -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FfiQuoteResponse.InvalidSignature -> {
                buf.putInt(4)
                FfiConverterTypeFfiQuoteRecipient.write(value.`recipient`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
